import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.Dj2sMFyx.js";const u=JSON.parse('{"title":"Kandelo Homebrew Packaging","description":"","frontmatter":{"lastUpdated":false},"headers":[{"level":2,"title":"The short version","slug":"the-short-version","link":"#the-short-version","children":[]},{"level":2,"title":"Vocabulary","slug":"vocabulary","link":"#vocabulary","children":[]},{"level":2,"title":"What each repository owns","slug":"what-each-repository-owns","link":"#what-each-repository-owns","children":[{"level":3,"title":"What comes from upstream Homebrew","slug":"what-comes-from-upstream-homebrew","link":"#what-comes-from-upstream-homebrew","children":[]},{"level":3,"title":"Tap names, Formula names, and GHCR paths","slug":"tap-names-formula-names-and-ghcr-paths","link":"#tap-names-formula-names-and-ghcr-paths","children":[]}]},{"level":2,"title":"What identifies a bottle","slug":"what-identifies-a-bottle","link":"#what-identifies-a-bottle","children":[]},{"level":2,"title":"The normal publication path","slug":"the-normal-publication-path","link":"#the-normal-publication-path","children":[{"level":3,"title":"1. Review the Formula","slug":"_1-review-the-formula","link":"#_1-review-the-formula","children":[]},{"level":3,"title":"2. Select exact Kandelo inputs","slug":"_2-select-exact-kandelo-inputs","link":"#_2-select-exact-kandelo-inputs","children":[]},{"level":3,"title":"3. Run a dry build","slug":"_3-run-a-dry-build","link":"#_3-run-a-dry-build","children":[]},{"level":3,"title":"4. Build and upload independently","slug":"_4-build-and-upload-independently","link":"#_4-build-and-upload-independently","children":[]},{"level":3,"title":"5. Bootstrap from a dry build when needed","slug":"_5-bootstrap-from-a-dry-build-when-needed","link":"#_5-bootstrap-from-a-dry-build-when-needed","children":[]},{"level":3,"title":"6. Verify the public bytes","slug":"_6-verify-the-public-bytes","link":"#_6-verify-the-public-bytes","children":[]},{"level":3,"title":"7. Finalize tap metadata","slug":"_7-finalize-tap-metadata","link":"#_7-finalize-tap-metadata","children":[]}]},{"level":2,"title":"Why tap main is append-only","slug":"why-tap-main-is-append-only","link":"#why-tap-main-is-append-only","children":[]},{"level":2,"title":"ABI changes and candidate pull requests","slug":"abi-changes-and-candidate-pull-requests","link":"#abi-changes-and-candidate-pull-requests","children":[{"level":3,"title":"There is no canonical candidate-bottle lane today","slug":"there-is-no-canonical-candidate-bottle-lane-today","link":"#there-is-no-canonical-candidate-bottle-lane-today","children":[]},{"level":3,"title":"Supported ABI-bump sequence","slug":"supported-abi-bump-sequence","link":"#supported-abi-bump-sequence","children":[]},{"level":3,"title":"Why not publish candidate bottles before merge?","slug":"why-not-publish-candidate-bottles-before-merge","link":"#why-not-publish-candidate-bottles-before-merge","children":[]}]},{"level":2,"title":"VFS images and lazy bottles","slug":"vfs-images-and-lazy-bottles","link":"#vfs-images-and-lazy-bottles","children":[]},{"level":2,"title":"brew inside a Kandelo guest","slug":"brew-inside-a-kandelo-guest","link":"#brew-inside-a-kandelo-guest","children":[]},{"level":2,"title":"Third-party taps","slug":"third-party-taps","link":"#third-party-taps","children":[]},{"level":2,"title":"Failures and safe retries","slug":"failures-and-safe-retries","link":"#failures-and-safe-retries","children":[]},{"level":2,"title":"Migration from packages/registry","slug":"migration-from-packages-registry","link":"#migration-from-packages-registry","children":[]},{"level":2,"title":"Where to look next","slug":"where-to-look-next","link":"#where-to-look-next","children":[]}],"relativePath":"reference/homebrew-packaging-system.md","filePath":"reference/homebrew-packaging-system.md"}'),r={name:"reference/homebrew-packaging-system.md"};function n(l,e,s,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="kandelo-homebrew-packaging" tabindex="-1">Kandelo Homebrew Packaging <a class="header-anchor" href="#kandelo-homebrew-packaging" aria-label="Permalink to &quot;Kandelo Homebrew Packaging&quot;">​</a></h1><p>This guide explains how Kandelo builds, publishes, and uses Homebrew packages. It starts with the small number of concepts needed to follow the system. The detailed security and file-format contracts remain in <a href="./homebrew-publishing">Homebrew Publishing</a>.</p><p>Kandelo is not Linux or macOS. A normal Homebrew bottle for those systems cannot run in Kandelo. Kandelo Formulae build WebAssembly programs for one Kandelo application binary interface (ABI) and architecture. The resulting archives use Homebrew&#39;s normal bottle format and tap layout, with extra Kandelo metadata for ABI checks, lazy virtual file system (VFS) composition, and browser validation.</p><p>This is an implementation and operations guide. Guest <code>brew install</code> commands are not a supported user promise until the public Node and browser lifecycle gates described below pass for the deployed image.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><p>The system has four main parts:</p><ol><li>A <strong>Formula</strong> says how to build one piece of software and names its dependencies.</li><li>A <strong>bottle</strong> is the prebuilt result for one Formula, Kandelo ABI, and WebAssembly architecture.</li><li>A <strong>tap</strong> publishes Formulae and bottle metadata. Kandelo&#39;s first-party tap is <code>kandelo-dev/tap-core</code>, stored in the GitHub repository <code>Kandelo-dev/homebrew-tap-core</code>.</li><li>A <strong>VFS image</strong> selects bottles and decides which files are present at boot and which bottles remain lazy until first use.</li></ol><p>The data moves through the system like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Formula + source + dependencies + Kandelo SDK</span></span>
<span class="line"><span>                       |</span></span>
<span class="line"><span>                       v</span></span>
<span class="line"><span>                 build a bottle</span></span>
<span class="line"><span>                       |</span></span>
<span class="line"><span>                       v</span></span>
<span class="line"><span>        public registry bottle + tap metadata</span></span>
<span class="line"><span>                       |</span></span>
<span class="line"><span>                       v</span></span>
<span class="line"><span>       verified eager or lazy VFS composition</span></span>
<span class="line"><span>                       |</span></span>
<span class="line"><span>                       v</span></span>
<span class="line"><span>             Node and browser execution</span></span></code></pre></div><p>Each bottle that finishes the complete publication path stands on its own for its Kandelo ABI. That path builds the bottle, publishes its child and version index, reads the exact bytes back anonymously, verifies the runtime, and records an immutable Formula handoff. If a batch builds ten Formulae and two fail, the eight completed results remain valid and usable. A named shell or prefix release may wait for a complete selected dependency closure. That product-level wait does not invalidate an independently completed bottle.</p><h2 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in Kandelo</th></tr></thead><tbody><tr><td>Formula</td><td>Homebrew Ruby that describes a source, dependencies, build, install, and test.</td></tr><tr><td>Bottle</td><td>A prebuilt Formula result for one ABI and architecture.</td></tr><tr><td>Tap</td><td>A Git repository containing Formulae and their published bottle blocks.</td></tr><tr><td>Keg</td><td>The installed directory for one Formula version under the Homebrew Cellar.</td></tr><tr><td>Sidecar</td><td>Kandelo metadata beside a Formula. It records ABI, architecture, hashes, provenance, VFS ownership, and validation evidence.</td></tr><tr><td>Package generation</td><td>An immutable architecture-specific closure of Kandelo program, library, and source-package inputs admitted for one current-main consumer. During migration, Formula builds, platform tools, and browser products can use it. It is not a Homebrew bottle release.</td></tr><tr><td>Bottle mirror</td><td>A content-addressed tap release containing one exact plan and copies of the lazy bottle payloads selected by an image. The plan is the allowlist; the payloads provide one closed transport for Node and browsers. The payloads are not baked into the VFS image.</td></tr><tr><td>Runtime layer</td><td>One or more deferred bottle payloads plus a descriptor that says where their files belong.</td></tr></tbody></table><h2 id="what-each-repository-owns" tabindex="-1">What each repository owns <a class="header-anchor" href="#what-each-repository-owns" aria-label="Permalink to &quot;What each repository owns&quot;">​</a></h2><p><code>Automattic/kandelo</code> owns the platform and publisher implementation:</p><ul><li>the SDK, sysroot, kernel ABI, and package resolver;</li><li>the reusable bottle workflow;</li><li>Formula and sidecar validators;</li><li>VFS composition and lazy-runtime support;</li><li>Node and browser acceptance tests; and</li><li>the documentation for these contracts.</li></ul><p><code>Kandelo-dev/homebrew-tap-core</code> owns the live first-party tap:</p><ul><li><code>Formula/</code> source recipes;</li><li>closed Formula-owned recipe input under <code>Kandelo/recipes/</code>;</li><li>Formula source builds and candidate bottle builds;</li><li>generated bottle blocks and sidecars;</li><li>publication and failure records; and</li><li>immutable VFS, runtime-layer, campaign, and handoff releases.</li></ul><p>Bottle bytes are public GitHub Container Registry (GHCR) objects owned by the tap repository. A conventional third-party repository named <code>Example/homebrew-tools</code> represents the tap <code>Example/tools</code> and owns its own Formulae, packages, and publication authority.</p><p>The directory <code>homebrew/homebrew-tap-core/</code> in the Kandelo repository is a test fixture and template. It is not the live tap.</p><p>During migration, a tap build may consume a package archive staged by a Kandelo pull request. That is a temporary bridge, not the final package authority. The migration is not complete until Formula builds, bottle artifacts, candidate custody, and publication all run under tap-owned workflows, and no Homebrew consumer gets Formula-owned software from Kandelo package staging. Kandelo continues to own the platform source, SDK, ABI, validators, and reusable workflow implementation.</p><h3 id="what-comes-from-upstream-homebrew" tabindex="-1">What comes from upstream Homebrew <a class="header-anchor" href="#what-comes-from-upstream-homebrew" aria-label="Permalink to &quot;What comes from upstream Homebrew&quot;">​</a></h3><p>Kandelo uses upstream Homebrew for the parts that make a tap a Homebrew tap:</p><ul><li>Formula Ruby and dependency resolution;</li><li>source and resource checksum handling;</li><li>build and test lifecycle hooks;</li><li>keg and Cellar layout;</li><li>bottle archive creation, <code>bottle do</code> metadata, and pouring; and</li><li>the <code>brew tap</code>, <code>brew install</code>, and receipt model.</li></ul><p>Kandelo does not reimplement those parts as a parallel package manager. It adds a reviewed platform patch for Kandelo bottle tags and the Kandelo guest prefix, plus isolation, provenance, public Open Container Initiative (OCI) transport, ABI validation, sidecars, and VFS composition around upstream Homebrew. The publisher pins an exact upstream Homebrew commit so a later Homebrew change cannot silently alter a reviewed run.</p><h3 id="tap-names-formula-names-and-ghcr-paths" tabindex="-1">Tap names, Formula names, and GHCR paths <a class="header-anchor" href="#tap-names-formula-names-and-ghcr-paths" aria-label="Permalink to &quot;Tap names, Formula names, and GHCR paths&quot;">​</a></h3><p>These three names are related, but they are not interchangeable:</p><ul><li>the repository is <code>Kandelo-dev/homebrew-tap-core</code>;</li><li>the Homebrew tap is <code>kandelo-dev/tap-core</code>; and</li><li>a Formula keeps its ordinary name, for example <code>zlib</code>.</li></ul><p>The corresponding OCI repository is under <code>ghcr.io/kandelo-dev/homebrew-tap-core/zlib</code>. GitHub may display the package name simply as <code>zlib</code>. Do not add <code>tap-core/</code> to the Formula name to imitate the tap name.</p><h2 id="what-identifies-a-bottle" tabindex="-1">What identifies a bottle <a class="header-anchor" href="#what-identifies-a-bottle" aria-label="Permalink to &quot;What identifies a bottle&quot;">​</a></h2><p>A bottle is not selected by its filename alone. Its identity includes at least:</p><ul><li>the tap and Formula;</li><li>the Formula version, revision, and bottle rebuild number;</li><li>the Kandelo ABI;</li><li><code>wasm32</code> or <code>wasm64</code>;</li><li>the Formula and closed recipe input;</li><li>the exact dependency bottles;</li><li>the SDK, sysroot, and build-policy inputs; and</li><li>the archive digest and public OCI manifest digest.</li></ul><p>Changing the ABI starts a new Kandelo bottle epoch, recorded in metadata under a name such as <code>bottles-abi-v43</code>. The GHCR repository may stay the same, but Kandelo metadata and cache identities prevent consumers from mixing ABI epochs. Changing a kernel without changing the ABI does not, by itself, require rebuilding unrelated bottles. Rebuild only when the ABI, Formula output, dependency closure, or a declared build input changed.</p><p>An unchanged bottle keeps the producer commit that actually built it. A later catalog, tap, or VFS release may select that bottle, but it must not rewrite the historical provenance to make the bytes look newly built.</p><p>Kandelo records the same bottle in two compatible ways:</p><ul><li>Homebrew&#39;s <code>bottle do</code> block lets <code>brew</code> find and verify it; and</li><li>the Kandelo sidecar lets the VFS builder and host verify its ABI, provenance, owned paths, lazy size, and runtime evidence.</li></ul><p>The sidecar adds checks; it does not replace Homebrew&#39;s metadata.</p><h2 id="the-normal-publication-path" tabindex="-1">The normal publication path <a class="header-anchor" href="#the-normal-publication-path" aria-label="Permalink to &quot;The normal publication path&quot;">​</a></h2><h3 id="_1-review-the-formula" tabindex="-1">1. Review the Formula <a class="header-anchor" href="#_1-review-the-formula" aria-label="Permalink to &quot;1. Review the Formula&quot;">​</a></h3><p>Put first-party Formulae in the live core tap. Prefer Homebrew&#39;s normal Formula domain-specific language (DSL). When a larger script is needed, place it in a checksummed, Formula-owned <code>Kandelo/recipes/&lt;formula&gt;/</code> tree. A Formula may temporarily call an old <code>packages/registry/</code> build, but that is migration debt and must be recorded.</p><p>The Formula must build through Kandelo&#39;s normal software development kit (SDK) and libc path. A package patch may adapt to a documented WebAssembly boundary, but it must not hide a Kandelo Portable Operating System Interface (POSIX) or kernel bug.</p><h3 id="_2-select-exact-kandelo-inputs" tabindex="-1">2. Select exact Kandelo inputs <a class="header-anchor" href="#_2-select-exact-kandelo-inputs" aria-label="Permalink to &quot;2. Select exact Kandelo inputs&quot;">​</a></h3><p>Canonical publication starts from the exact current commit <code>M</code> of <code>Automattic/kandelo</code> <code>main</code>. The workflow records <code>M</code> and checks that it is still current immediately before every registry, release, or tap write. A commit that is merely an ancestor of <code>main</code> is not ordinary publication authority.</p><p>Some Formulae still need Kandelo package archives as build tools or migration inputs. Those archives come from a content-addressed package generation admitted against exact current <code>main</code>. Each archive retains the producer <code>S</code> that actually built it. Usually <code>S</code> and <code>M</code> are the same commit. After an ABI candidate is merged, activation may instead prove that the complete tree at tested producer <code>S</code> is identical to the tree at final main commit <code>M</code>.</p><p>The publisher downloads and verifies the whole generation locally. It never treats a mutable staging URL as authority. It also never rewrites <code>built_from</code> to make old bytes appear newly built: <code>S</code> remains the archive producer, while <code>M</code> is recorded separately as the commit that admitted those bytes for publication. Later validation, public transport, and VFS selection are separate evidence.</p><h3 id="_3-run-a-dry-build" tabindex="-1">3. Run a dry build <a class="header-anchor" href="#_3-run-a-dry-build" aria-label="Permalink to &quot;3. Run a dry build&quot;">​</a></h3><p>The tap&#39;s reviewed <code>dry-run-bottles.yml</code> caller invokes Kandelo&#39;s reusable publisher without write jobs. A dry run proves the real isolated builder and verifier paths, but it does not upload a package, edit the tap, or publish a release.</p><p>Pull-request code must not call the complete reusable publisher. GitHub checks the permissions of every job in a reusable workflow, including write jobs that a dry-run condition would skip. Giving that permission ceiling to untrusted PR code would cross the publication boundary.</p><h3 id="_4-build-and-upload-independently" tabindex="-1">4. Build and upload independently <a class="header-anchor" href="#_4-build-and-upload-independently" aria-label="Permalink to &quot;4. Build and upload independently&quot;">​</a></h3><p>The trusted tap caller invokes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.github/workflows/reusable-homebrew-bottle-publish.yml</span></span></code></pre></div><p>The workflow plans the dependency graph, then builds every ready Formula and architecture with as much concurrency as the graph permits. Build jobs do not receive package or tap write credentials.</p><p>Separate jobs validate a bounded handoff and upload only the already-checked OCI layout. The publisher first writes an architecture-specific child, then a Homebrew version index. It immediately reads the object back anonymously by digest. A package that is private, missing, changed, or not anonymously readable cannot reach tap finalization.</p><p>New packages are created under the public tap repository&#39;s GHCR namespace. The proven path uses the repository-scoped <code>GITHUB_TOKEN</code>, a source annotation for that public repository, organization permission for public package creation, and inherited repository access. New packages have been public at creation on that path, so the normal publisher does not need a package personal access token (PAT). GitHub&#39;s settings are not treated as proof by themselves: every publication must still pass anonymous exact-digest readback before tap finalization. The publisher does not repair visibility after upload.</p><h3 id="_5-bootstrap-from-a-dry-build-when-needed" tabindex="-1">5. Bootstrap from a dry build when needed <a class="header-anchor" href="#_5-bootstrap-from-a-dry-build-when-needed" aria-label="Permalink to &quot;5. Bootstrap from a dry build when needed&quot;">​</a></h3><p>A Formula&#39;s first bottle is different from later publications because its GHCR package repository does not exist yet. The normal publisher can create that repository while publishing the bottle. The core tap also has a bounded, one-time first-child workflow for the prefix campaign. It accepts only the dry-build artifacts produced earlier in that same protected workflow run and attempt. This helper is not required for every new Formula. It publishes actual bottle bytes, not an empty marker package.</p><p>First run the normal credential-free dry build. The protected tap workflow then accepts exactly one successful dry-run child artifact. It binds the run, attempt, artifact digest, bottle manifest digest, protected caller, and exact admitted tap and Kandelo source commits. It also checks the required protected-<code>main</code> ancestry and proves through an authenticated query that neither a public nor a private package already owns the destination.</p><p>The workflow uploads only that immutable architecture-specific child with the tap repository&#39;s <code>GITHUB_TOKEN</code>, removes its credentials, and reads the exact digest back anonymously. It does not publish the Formula&#39;s version index, edit the tap, generate sidecars, or claim that the Formula is ready. A retry never uploads the child twice. It may re-prove the exact already-public child without credentials; a different or private existing object fails closed.</p><p>After this bootstrap, run the normal publisher. That publisher creates the version index, verifies the bottle through Kandelo, and finalizes the Formula and sidecars. A failure in that later work does not erase the already public child, but normal <code>brew install</code> selection is not complete until the version index and tap metadata are finalized.</p><p>This dedicated first-child caller is currently implemented for the protected first-party tap. A new third-party tap must provide an equivalently reviewed protected caller or use its normal publication path and pass the same public package and anonymous-readback acceptance checks. Do not copy the first-party workflow and describe it as a generic facility without adapting its explicit repository checks.</p><h3 id="_6-verify-the-public-bytes" tabindex="-1">6. Verify the public bytes <a class="header-anchor" href="#_6-verify-the-public-bytes" aria-label="Permalink to &quot;6. Verify the public bytes&quot;">​</a></h3><p>The verifier starts from fresh source checkouts. In write mode it ignores the builder&#39;s private bottle copy and downloads the public bottle by its exact digest. It pours the bottle, runs the Formula test through Kandelo, and checks the ABI and runtime contract.</p><p>Browser-compatible claims require browser evidence. A Node-only pass cannot mark a bottle as browser compatible.</p><h3 id="_7-finalize-tap-metadata" tabindex="-1">7. Finalize tap metadata <a class="header-anchor" href="#_7-finalize-tap-metadata" aria-label="Permalink to &quot;7. Finalize tap metadata&quot;">​</a></h3><p>Only after public readback and runtime verification does the finalizer write the Formula bottle block, Kandelo sidecar, and provenance report. Related Formulae in one requested batch are finalized together when the selected operation requires one coherent tap commit.</p><p>After index publication and anonymous readback, the bottle object is immutable and independently usable by exact digest. Tap finalization makes normal Homebrew Formula resolution select it.</p><h2 id="why-tap-main-is-append-only" tabindex="-1">Why tap <code>main</code> is append-only <a class="header-anchor" href="#why-tap-main-is-append-only" aria-label="Permalink to &quot;Why tap \`main\` is append-only&quot;">​</a></h2><p>The tap&#39;s <code>main</code> branch is part of the package trust chain. It names the reviewed Formula, the workflow caller, and the metadata that selects public bottle bytes. An ancestry check is useful only while the history remains append-only: a commit that authorized a bottle must not later disappear through branch deletion or a non-fast-forward rewrite.</p><p>The intended repository rules are:</p><ul><li>block branch deletion and non-fast-forward updates;</li><li>require pull requests for human-authored changes;</li><li>allow rebase merges only;</li><li>require the current-base <code>publisher-trust</code> check; and</li><li>provide one explicit automation path for generated Formula and sidecar fast-forward commits.</li></ul><p>Do not give every workflow or repository writer an unrestricted bypass. The current publisher writes generated tap state directly with the repository&#39;s <code>GITHUB_TOKEN</code>, while GitHub rulesets do not allow the platform-owned GitHub Actions integration to be selected as this repository&#39;s bypass actor. Until the publisher uses a dedicated app, deploy key, or reviewed PR finalization path, this remains a known protection gap. Keep the exact-main rechecks, pinned callers, read-only PR token policy, and publication locks enabled; do not describe them as a substitute for complete branch protection.</p><p>As of 2026-08-01, the live tap enforces that append-only history property through the <code>Protect tap main history</code> ruleset: <code>main</code> cannot be deleted or moved with a non-fast-forward push. This prevents an accepted commit from being removed. It does not prevent an authorized actor from adding a direct fast-forward commit, so it is not complete branch protection. The ruleset deliberately does not yet require a pull request or status check. Enabling either requirement without a valid automation identity would stop the bottle finalizer.</p><h2 id="abi-changes-and-candidate-pull-requests" tabindex="-1">ABI changes and candidate pull requests <a class="header-anchor" href="#abi-changes-and-candidate-pull-requests" aria-label="Permalink to &quot;ABI changes and candidate pull requests&quot;">​</a></h2><p>An ABI bump changes the contract between Kandelo programs and the kernel. Every bottle for the new ABI must therefore be rebuilt, even when the upstream software version did not change.</p><h3 id="there-is-no-canonical-candidate-bottle-lane-today" tabindex="-1">There is no canonical candidate-bottle lane today <a class="header-anchor" href="#there-is-no-canonical-candidate-bottle-lane-today" aria-label="Permalink to &quot;There is no canonical candidate-bottle lane today&quot;">​</a></h3><p>The Kandelo merge-candidate workflow can build package-registry archives for the proposed ABI, create an isolated candidate index, and run kernel, libc, POSIX, Node, and browser validation against the synthetic merge. These are candidate artifacts. They are valuable test evidence, but Prepare Merge does not publish public canonical Homebrew bottles.</p><p>The complete Homebrew publisher intentionally cannot run from PR-controlled workflow code. Ordinary canonical publication also requires exact protected <code>main</code> authority. A pull-request head, a synthetic merge, or a commit that may become an ancestor later does not satisfy that rule. Tree equality is used after merge to admit package-generation inputs; it does not turn a pre-merge Homebrew bottle into a canonical publication.</p><p>The reviewed prefix-campaign mode is a narrow exception for a sealed source commit that is already in protected <code>main</code> history. It may continue while that exact source remains an ancestor, and it preserves that source in bottle provenance. It never admits a PR-only commit.</p><p>A workflow already reviewed on protected tap <code>main</code> may select an unmerged Kandelo SHA as read-only input for a no-write dry run. The trusted workflow, not the selected candidate, still owns the job graph and permissions. This is useful for ABI-neutral publisher or Formula testing when all required package inputs already exist. It does not make the candidate protected or canonical.</p><p>That dry-run path is not a complete new-ABI bottle prebuild. A new ABI does not yet have the durable package generations needed by the bottle builder, and dry runs are not allowed to create or substitute those generations.</p><h3 id="supported-abi-bump-sequence" tabindex="-1">Supported ABI-bump sequence <a class="header-anchor" href="#supported-abi-bump-sequence" aria-label="Permalink to &quot;Supported ABI-bump sequence&quot;">​</a></h3><p>Use this sequence for an ABI candidate:</p><ol><li>Update <code>ABI_VERSION</code>, <code>abi/snapshot.json</code>, and the ABI-bound generated bindings, locks, or manifests required by validation. Do not mass-edit package URLs: <code>{abi}</code> substitution and package cache identity select the new ABI automatically.</li><li>Run Prepare Merge. It builds the complete stale package closure for the synthetic merge, creates an isolated candidate index, and runs the relevant kernel, libc, POSIX, Node, and browser suites. Fix the platform before adding package-specific workarounds.</li><li>Merge the exact prepared tree. The post-merge <code>activate-merge-candidate.yml</code> workflow verifies that the tested producer tree equals the resulting <code>main</code> tree, creates the new <code>binaries-abi-v&lt;N&gt;</code> release, copies the complete tested closure, commits one canonical index transaction, and publishes the release once. <code>force-rebuild.yml</code> is not the initializer for a new ABI release.</li><li>Read the final <code>main</code> commit <code>M</code> and the immutable archive producer <code>S</code> from activation evidence. Promote the required roots with <code>promote-package-generation.yml</code>, using <code>identical-git-tree-v1</code> to prove that the complete <code>S</code> tree equals <code>M</code>. The archives keep truthful <code>S</code> provenance even when <code>S</code> and <code>M</code> are different commit identities.</li><li>Rotate the tap&#39;s pinned Kandelo workflow trust to <code>M</code> and run a no-write bottle canary.</li><li>Publish Formulae in dependency order. Run independent branches in parallel. Each anonymously verified bottle becomes usable immediately; do not wait for unrelated failures before consuming it by immutable digest.</li><li>Recompose and validate the selected VFS image. Deploy only the image and guest lifecycle claims that passed both Node and browser evidence.</li></ol><p>An ABI bump does not require one all-or-nothing full-catalog bottle transaction. The dependency graph imposes ordering, but independent leaves can publish at the same time and successful results remain useful.</p><h3 id="why-not-publish-candidate-bottles-before-merge" tabindex="-1">Why not publish candidate bottles before merge? <a class="header-anchor" href="#why-not-publish-candidate-bottles-before-merge" aria-label="Permalink to &quot;Why not publish candidate bottles before merge?&quot;">​</a></h3><p>Publishing before merge would make unmerged code a public package authority. Preserving a PR commit with a merge commit only proves that it became an ancestor; it does not prove that the bottle was produced from the final protected-main identity. Kandelo does not use that history trick as the normal release model.</p><p>A future safe prebuild lane is possible, but it needs an explicit design. At minimum it must:</p><ul><li>build without registry or tap write credentials;</li><li>store candidate bottles in a quarantined, run-bound namespace;</li><li>bind the exact Formula, dependencies, SDK, sysroot, ABI, and synthetic merge tree;</li><li>after merge, prove that every output-affecting input is identical to final <code>main</code>;</li><li>preserve the candidate producer in immutable <code>built_from</code> provenance and record final-main validation as separate admission evidence; and</li><li>publish through a trusted default-branch workflow that rechecks all public destinations before mutation.</li></ul><p>Until that promotion contract exists, build and test the ABI and package candidate before merge, activate its complete package closure after merge, then build Homebrew bottles through exact-main publication.</p><h2 id="vfs-images-and-lazy-bottles" tabindex="-1">VFS images and lazy bottles <a class="header-anchor" href="#vfs-images-and-lazy-bottles" aria-label="Permalink to &quot;VFS images and lazy bottles&quot;">​</a></h2><p>A VFS image chooses policy; it is not another package format.</p><p>Files that are always needed, such as the shell used to boot the shell image, can be materialized into the image. Less common programs remain lazy. Their directory metadata is present so <code>stat</code> and <code>readdir</code> work, but the first file content access downloads and verifies the complete owning bottle, then materializes its selected tree atomically.</p><p>Lazy access currently downloads a whole bottle archive. It does not fetch one TAR member or use HTTP range requests. Each dependency remains a separate immutable bottle transport. A sealed atomic runtime cohort may activate its selected dependency members together so the program never observes a partial closure; unrelated bottles remain lazy.</p><p>Small, independent command binaries from a bundle such as <code>posix-utils-lite</code> may later use per-program lazy references. A program such as Vim needs runtime data beside its executable and should normally activate its complete bottle tree.</p><p>The VFS image embeds the exact bottle-mirror plan. A separate immutable tap release contains that plan and one verified copy of every deferred payload. The plan records each URL, digest, and size. Browser code must not turn an arbitrary URL in VFS metadata into network authority.</p><h2 id="brew-inside-a-kandelo-guest" tabindex="-1"><code>brew</code> inside a Kandelo guest <a class="header-anchor" href="#brew-inside-a-kandelo-guest" aria-label="Permalink to &quot;\`brew\` inside a Kandelo guest&quot;">​</a></h2><p>Guest Homebrew has two separate inputs:</p><ol><li><code>homebrew-bootstrap</code> contains one reviewed upstream Homebrew source tree plus Kandelo&#39;s guest-platform patch and environment policy.</li><li>A bottle-backed runtime-support closure supplies Ruby and the ordinary tools that Homebrew needs.</li></ol><p>The base shell can expose <code>/usr/bin/brew</code> as a lazy activation reference. A user who never runs <code>brew</code> does not pay the bootstrap and Ruby download cost. An opt-in demo image may materialize the same layer in advance.</p><p>A valid lifecycle test must use the real guest command to tap a separate repository, resolve dependencies, install its public bottle, run it, upgrade or remove it where claimed, and survive the supported reboot or snapshot boundary. Preinstalling the third-party result into the demo would not prove guest Homebrew.</p><p>The campaign&#39;s canonical Kandelo guest prefix is <code>/opt/kandelo/homebrew</code>. Host Homebrew prefixes are not guest paths. The currently deployed bottle-backed shell still uses the retired guest layout recorded in the machine-readable contract. The campaign must change the Formulae, bootstrap, and shell image together before <code>/opt</code> is described as deployed behavior.</p><p>The first supported guest path will install prebuilt bottles. Building a Formula entirely inside Kandelo is future work. It will use the same Formula and tap model once the guest has a complete supported Clang/LLVM toolchain and the remaining build-host capabilities.</p><h2 id="third-party-taps" tabindex="-1">Third-party taps <a class="header-anchor" href="#third-party-taps" aria-label="Permalink to &quot;Third-party taps&quot;">​</a></h2><p>A third-party tap uses the same Formula, bottle, and sidecar contracts as the core tap. It owns its GitHub repository, GHCR namespace, workflow caller, and visibility policy. Kandelo validates that the repository name and tap name match Homebrew&#39;s conventional mapping.</p><p>The publication foundation is already proven for an independent user-owned tap: public GHCR creation, anonymous readback, tap finalization, and a Node-and-Chromium VFS canary are green. The complete in-guest third-party <code>brew tap</code> and <code>brew install</code> lifecycle is still rollout work. Upgrade, expected failure, reboot persistence, and in-guest source builds must not be claimed until their own lifecycle evidence passes.</p><p>The remaining first in-guest lifecycle proof should remain small:</p><ul><li>one Formula in a separate public tap;</li><li>one public bottle built for the active Kandelo ABI;</li><li>no hidden core-tap fallback;</li><li>a live in-guest <code>brew tap</code> and <code>brew install</code>; and</li><li>anonymous bottle retrieval in both Node and Chromium.</li></ul><p>After that proof, adding more third-party Formulae is ordinary dependency-graph work rather than a new platform exception.</p><h2 id="failures-and-safe-retries" tabindex="-1">Failures and safe retries <a class="header-anchor" href="#failures-and-safe-retries" aria-label="Permalink to &quot;Failures and safe retries&quot;">​</a></h2><ul><li>A failed Formula does not invalidate successful siblings.</li><li>Never blindly repeat a first-package publication after an ambiguous upload. Inspect the workflow run and GHCR repository first.</li><li>Immutable releases are content-addressed. A conflicting tag or asset is an error, not something to overwrite.</li><li>Formula, source, application programming interface (API), tap, or <code>main</code> drift stops a write. Re-plan from the new exact source instead of relaxing the comparison.</li><li>The native Homebrew compatibility lock is reviewed generated data. Refresh it from the exact pinned Homebrew executable on Linux, inspect the upstream Formula change, and require byte-for-byte equality in continuous integration (CI).</li><li>Publication and finalization use locks, but locks do not replace digest, ancestry, or public-readback checks.</li></ul><h2 id="migration-from-packages-registry" tabindex="-1">Migration from <code>packages/registry</code> <a class="header-anchor" href="#migration-from-packages-registry" aria-label="Permalink to &quot;Migration from \`packages/registry\`&quot;">​</a></h2><p>The old Kandelo registry remains only while a Formula still calls a registry build or while a non-Homebrew platform artifact has no proper owner. A Formula file by itself is not proof that migration finished.</p><p>Registry retirement is separate from old container-package cleanup. Live bottles use the <code>homebrew-tap-core/*</code> GHCR namespace. Historical private <code>tap-core/*</code> or older canary packages are not current Formula inputs, and removing those controls must not delete immutable live or last-green bottle bytes used for rollback.</p><p>For each migrated package:</p><ol><li>move the portable recipe into normal Formula DSL or a closed tap recipe;</li><li>publish and verify every required architecture;</li><li>switch VFS and consumer selection to the bottle and sidecar;</li><li>remove the Formula&#39;s registry bridge;</li><li>prove no source, build, CI, or image caller still owns the registry entry; and only then</li><li>delete the obsolete registry recipe and archive reference.</li></ol><p>The migration ledger and current execution order live in the <a href="https://github.com/Automattic/kandelo/blob/main/docs/plans/2026-07-21-homebrew-migration-execution-plan.md" target="_blank" rel="noreferrer">Homebrew migration plan</a>.</p><h2 id="where-to-look-next" tabindex="-1">Where to look next <a class="header-anchor" href="#where-to-look-next" aria-label="Permalink to &quot;Where to look next&quot;">​</a></h2><ul><li><a href="./homebrew-publishing">Homebrew Publishing</a> is the detailed trust, workflow, schema, OCI, VFS, and recovery reference.</li><li><a href="https://github.com/Automattic/kandelo/blob/main/docs/porting-guide.md#homebrew-formula-authoring" target="_blank" rel="noreferrer">Porting Guide</a> explains how to author a Formula and closed recipe.</li><li><a href="https://github.com/Automattic/kandelo/blob/main/docs/abi-versioning.md" target="_blank" rel="noreferrer">ABI Versioning</a> defines when the ABI must change and how Kandelo rejects mismatched programs.</li><li><a href="https://github.com/Automattic/kandelo/blob/main/docs/binary-releases.md" target="_blank" rel="noreferrer">Binary Releases</a> explains Kandelo package generations and why they are separate from Homebrew bottles.</li><li><a href="https://github.com/Automattic/kandelo/blob/main/docs/package-management.md" target="_blank" rel="noreferrer">Package Management</a> documents the legacy resolver and the remaining bridge contract.</li></ul>`,117)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
